import sys
from collections import defaultdict, deque

input = sys.stdin.readline

def count_paths(n, edges, start):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Initialize distances and ways arrays
    dist = [-1] * (n + 1)
    ways = [0] * (n + 1)
    dist[start] = 0
    ways[start] = 1

    # BFS to find shortest paths
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
            if dist[v] == dist[u] + 1:
                ways[v] += ways[u]

    # Check for cycles
    for u in range(1, n + 1):
        for v in graph[u]:
            if dist[u] + 1 == dist[v] and ways[v] > 1:
                return -1

    return ways[1:]

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n, m = map(int, input().split())
        edges = [tuple(map(int, input().split())) for _ in range(m)]
        input()  # Consume the empty line

        # Count paths from vertex 1
        paths = count_paths(n, edges, 1)
        results.append(paths)

    # Output results
    for result in results:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
